INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(2981,1,0,'Earth Mother, into your arms we give one of our own. She is Unaya Hawkwind, my mother, and Greatmother to us all; the wisest of our tribe.',12,0,100,1,0,0,38303,0,'Chief Hawkwind'),
(2981,2,0,'May her spirit fly to you swiftly; may the winds carry her gently, and the grass whisper her name.',12,0,100,1,0,0,38304,0,'Chief Hawkwind'),
(2981,3,0,'Watch over her as she has watched over us; let her look down on us with joy, through the eternal gaze of An\'she and Mu\'sha, until we too join her in death.',12,0,100,1,0,0,38305,0,'Chief Hawkwind ');
